do $test$
declare u uuid:=gen_random_uuid();other uuid:=gen_random_uuid();s jsonb;trip uuid;op uuid;first_op uuid;
 boat uuid;cost integer;initial_fuel integer:=1000;n integer;old_snapshot jsonb;
 seed double precision;candidate integer;low_count integer;high_count integer;
begin
 insert into auth.users(id) values(u),(other);
 insert into public.player_profiles(id,nickname) values(u,'취소검증'||left(u::text,6)),(other,'취소타인'||left(other::text,6));
 perform set_config('request.jwt.claim.sub',u::text,true);
 insert into public.player_wallets(user_id,gold,inventory) values(u,100000,'{"fuel":1000}') on conflict(user_id) do update set gold=100000,inventory=excluded.inventory;
 set local role authenticated;
 s:=public.harbor_action('buy',gen_random_uuid(),'billow-rider');
 s:=public.harbor_action('depart',gen_random_uuid(),'billow-rider');
 reset role;
 trip:=(s#>>'{receipt,voyageId}')::uuid;
 select boat_id,vessel_snapshot,(vessel_snapshot->>'fuel_cost')::integer into boat,old_snapshot,cost from public.harbor_voyages where id=trip;
 op:=gen_random_uuid();first_op:=op;
 set local role authenticated;
 s:=public.cancel_harbor_voyage(trip,op,true);
 if (s#>>'{receipt,refundedFuel}')::integer<>cost or (s->>'fuel')::integer<>initial_fuel then raise exception 'REFUND_WRONG';end if;
 if jsonb_array_length(s->'voyages')<>0 then raise exception 'ACTIVE_CANCELLED_VOYAGE';end if;
 s:=public.cancel_harbor_voyage(trip,op,true);
 if not (s->>'replayed')::boolean or (s->>'fuel')::integer<>initial_fuel then raise exception 'REFUND_REPLAY_WRONG';end if;
 begin perform public.cancel_harbor_voyage(trip,op,false);raise exception 'CONFLICT_ALLOWED';exception when others then if sqlerrm<>'OPERATION_CONFLICT' then raise;end if;end;
 reset role;
 if not exists(select 1 from app_private.cancelled_harbor_voyages where voyage_id=trip and voyage->'vessel_snapshot'=old_snapshot and refunded_fuel=cost) then raise exception 'AUDIT_MISSING';end if;
 -- Pick a random stream that would draw a different attempt count without the
 -- reuse guard. This makes the regression fail if the protection is removed.
 select fishing_count,fishing_count_max into low_count,high_count from public.harbor_vessels where id='billow-rider';
 for n in 1..20 loop
  seed:=n/20.0;perform setseed(seed);
  candidate:=low_count+floor(random()*(high_count-low_count+1))::integer;
  exit when candidate<>(old_snapshot->>'fishing_count')::integer;
 end loop;
 if candidate=(old_snapshot->>'fishing_count')::integer then raise exception 'INVALID_REROLL_FIXTURE';end if;
 perform setseed(seed);
 set local role authenticated;
 begin perform 1 from app_private.cancelled_harbor_voyages;raise exception 'ARCHIVE_READ_ALLOWED';exception when insufficient_privilege then null;end;
 s:=public.harbor_action('depart',gen_random_uuid(),null,null,1,boat);
 reset role;
 trip:=(s#>>'{receipt,voyageId}')::uuid;
 if (select vessel_snapshot->'fishing_count' from public.harbor_voyages where id=trip) is distinct from old_snapshot->'fishing_count' then raise exception 'FREE_CANCEL_REROLLED_COUNT';end if;
 update public.harbor_voyages set departed_at=clock_timestamp()-interval '31 seconds' where id=trip;
 set local role authenticated;
 begin perform public.cancel_harbor_voyage(trip,gen_random_uuid(),true);raise exception 'STALE_QUOTE_ALLOWED';exception when others then if sqlerrm<>'CANCELLATION_QUOTE_CHANGED' then raise;end if;end;
 reset role;
 if not exists(select 1 from public.harbor_voyages where id=trip) then raise exception 'STALE_QUOTE_CHANGED_TRIP';end if;
 perform set_config('request.jwt.claim.sub',other::text,true);
 set local role authenticated;
 begin perform public.cancel_harbor_voyage(trip,gen_random_uuid(),false);raise exception 'FOREIGN_TRIP_CANCELLED';exception when others then if sqlerrm<>'VOYAGE_NOT_FOUND' then raise;end if;end;
 reset role;
 perform set_config('request.jwt.claim.sub',u::text,true);
 set local role authenticated;
 op:=gen_random_uuid();s:=public.cancel_harbor_voyage(trip,op,false);
 if (s#>>'{receipt,refundedFuel}')::integer<>0 or (s->>'fuel')::integer<>initial_fuel-cost then raise exception 'EMERGENCY_REFUND_WRONG';end if;
 s:=public.harbor_action('claim_all',gen_random_uuid());
 if jsonb_array_length(s#>'{receipt,results}')<>0 then raise exception 'CANCELLED_REWARDS';end if;
 s:=public.harbor_action('depart',gen_random_uuid(),null,null,1,boat);
 reset role;
 trip:=(s#>>'{receipt,voyageId}')::uuid;
 update public.harbor_voyages set departed_at=clock_timestamp()-interval '1 hour',returns_at=clock_timestamp()-interval '1 second' where id=trip;
 set local role authenticated;
 begin perform public.cancel_harbor_voyage(trip,gen_random_uuid(),false);raise exception 'RETURNED_TRIP_CANCELLED';exception when others then if sqlerrm<>'VOYAGE_ALREADY_RETURNED' then raise;end if;end;
 reset role;
 if (select count(*) from app_private.cancelled_harbor_voyages where user_id=u)<>2 then raise exception 'CANCEL_COUNT_WRONG';end if;
 if exists(select 1 from public.player_collectibles where user_id=u) then raise exception 'CANCEL_GRANTED_CATCH';end if;
 if not exists(select 1 from public.harbor_boats where id=boat and user_id=u and sold_at is null and dock_slot is not null) then raise exception 'BOAT_OWNERSHIP_CHANGED';end if;
 set local role anon;
 begin perform public.cancel_harbor_voyage(trip,gen_random_uuid(),false);raise exception 'ANON_CANCEL_ALLOWED';exception when insufficient_privilege then null;end;
 reset role;
end $test$;
